namespace ghidra.app.plugin.core.diff;

using ghidra.framework.cmd;
using ghidra.program.model.listing;
using ghidra.util.task;

/**
 * Command to apply diffs to current program.
 */
class NextDiffCommand : BackgroundCommand<Program> {

	private ProgramDiffPlugin plugin;

	NextDiffCommand(ProgramDiffPlugin plugin) : base("Next Difference", false, false, true)
    {
		this.plugin = plugin;
	}

	/* @Override */
	public bool applyTo(Program program, TaskMonitor monitor) {
		monitor.setMessage("NextDiffTask starting...");
		plugin.nextDiff();
		return true;
	}
}
